#!/usr/bin/env bash
# bcjob.template.sh -- probe/base job for the ONE Bowen–Chapman campaign clone (runs ON MSI; generated by
# bcprobe.sh / bcbase.sh through the shared nm dispatch.sh). Under the clone lock: delta-sync origin/main@SHA
# from the shared MSI mirror into the clone (every synced path except the overlay), apply the overlay, purge
# transitively stale oleans, build the named modules with the shared Lake artifact cache.
# So a GREEN certifies exactly origin/main@SHA + the overlay bytes.
#
# Sync guards (09-12, after origin/main was gutted by a lander whose read-tree failed on a full disk):
#  G1 refuse to sync to a SHA whose tree lacks GroupApproximation.lean, lake-manifest.json or lakefile.toml;
#  G2 every git listing, diff and show the sync consumes must exit 0;
#  G3 a source path is deleted only when the synced tree lacks it, confirmed by a second, independent lookup;
#  G4 after the sync the clone's synced paths must equal the SHA's tree exactly (apart from overlay paths).
#  A failure after the first write marks the clone PREP_PENDING, so no probe builds on a half-synced tree.
set -u
P=/projects/standard/__MSI_GROUP__/__MSI_USER__
export HOME=$P ELAN_HOME=$P/.elan XDG_CACHE_HOME=$P/.cache PATH=$P/.elan/bin:$PATH
CLONE=$P/bc_clones/bc; TAG=__TAG__; SHA=__SHA__; MODS="__MODS__"; LANE=__LANE__
NMR=$P/nm; MIR=$NMR/mirror.git
LOG=$CLONE/.nm/build-$TAG.log
export LEAN_NUM_THREADS=${NT:-8}
SYNC_PATHS="GroupApproximation GroupApproximation.lean Palomar lakefile.toml lake-manifest.json lean-toolchain"
csort() { LC_ALL=C sort "$@"; }
ccomm() { LC_ALL=C comm "$@"; }
summary_fail() { echo "===== SUMMARY"; echo "lane $LANE tag $TAG"; echo "$1"; echo "REAL_EXIT=${2:-4}"; exit "${2:-4}"; }
sync_fail() { touch "$CLONE/.nm/PREP_PENDING"; summary_fail "$1; clone marked PREP_PENDING until infra re-verifies its sources (infra)"; }
exec 9>"$CLONE/.lake/laneprobe.lock"
# Lock contention record: a waiting marker while the job waits, then one row (tag, lane, job start, lock acquired)
# appended under the lock; tools/bc-swarm/remote/lockstats.sh reads both.
TJ0=$(date +%s); echo "$TJ0 $LANE" > "$CLONE/.nm/waiting-$TAG"
echo "[job] $(date +%T) $(hostname -s) lane=$LANE waiting for clone lock"
flock -w 14400 9 || { rm -f "$CLONE/.nm/waiting-$TAG"; summary_fail "PROBE FAILED: clone lock not free after 4 h (infra)" 3; }
TJL=$(date +%s); rm -f "$CLONE/.nm/waiting-$TAG"
printf '%s\t%s\t%s\t%s\n' "$TAG" "$LANE" "$TJ0" "$TJL" >> "$CLONE/.nm/lockwait.tsv"
echo "[job] $(date +%T) clone lock acquired after $((TJL - TJ0)) s"
[ -e "$CLONE/.nm/PREP_PENDING" ] && summary_fail "PROBE DEFERRED: clone preparation in progress; retry later" 5
exec 8>"$NMR/mirror.lock"; flock -w 900 8 || summary_fail "PROBE FAILED: mirror lock busy (infra)"
git -C "$MIR" fetch -q origin 2>/dev/null
exec 8>&-
git -C "$MIR" cat-file -e "$SHA^{commit}" || summary_fail "PROBE FAILED: MSI mirror lacks $SHA (infra)"
# G1
for root in GroupApproximation.lean lake-manifest.json lakefile.toml; do
  git -C "$MIR" cat-file -e "$SHA:$root" 2>/dev/null \
    || summary_fail "PROBE FAILED: origin/main@${SHA:0:9} lacks $root; refusing to sync a gutted tree (infra)"
done
OV=$CLONE/.nm/ov-$TAG; mkdir -p "$OV"
( cd "$OV" && find . -type f | sed 's|^\./||' ) | csort > "$CLONE/.nm/ovpaths-$TAG"
LAST=$(cat "$CLONE/.nm/base" 2>/dev/null)
git -C "$MIR" cat-file -e "$LAST^{commit}" 2>/dev/null || summary_fail "PROBE FAILED: clone base '$LAST' not in the mirror (infra)"
# G2
git -C "$MIR" ls-tree -r --name-only "$SHA" -- $SYNC_PATHS > "$CLONE/.nm/tree-$TAG.raw" \
  || summary_fail "PROBE FAILED: ls-tree of ${SHA:0:9} (infra)"
csort "$CLONE/.nm/tree-$TAG.raw" > "$CLONE/.nm/tree-$TAG"; rm -f "$CLONE/.nm/tree-$TAG.raw"
[ -s "$CLONE/.nm/tree-$TAG" ] || summary_fail "PROBE FAILED: empty tree listing for ${SHA:0:9} (infra)"
git -C "$MIR" diff --name-only --no-renames "$LAST" "$SHA" -- $SYNC_PATHS > "$CLONE/.nm/delta-$TAG" \
  || summary_fail "PROBE FAILED: delta diff ${LAST:0:9}..${SHA:0:9} (infra)"
touch "$CLONE/.nm/lastov"
{ ccomm -23 <(csort "$CLONE/.nm/lastov") "$CLONE/.nm/ovpaths-$TAG"; cat "$CLONE/.nm/delta-$TAG"; } \
  | csort -u | ccomm -23 - "$CLONE/.nm/ovpaths-$TAG" > "$CLONE/.nm/todo-$TAG"
nchg=0; ndel=0
while IFS= read -r path; do
  [ -n "$path" ] || continue
  if grep -qxF -- "$path" "$CLONE/.nm/tree-$TAG"; then
    mkdir -p "$CLONE/$(dirname "$path")"
    git -C "$MIR" show "$SHA:$path" > "$CLONE/$path.bctmp" || sync_fail "PROBE FAILED: delta sync of $path"
    if cmp -s "$CLONE/$path.bctmp" "$CLONE/$path"; then rm -f "$CLONE/$path.bctmp"; else mv "$CLONE/$path.bctmp" "$CLONE/$path"; nchg=$((nchg+1)); fi
  elif [ -e "$CLONE/$path" ]; then
    # G3
    if git -C "$MIR" cat-file -e "$SHA:$path" 2>/dev/null; then
      sync_fail "PROBE FAILED: refusing to delete $path, which origin/main@${SHA:0:9} still has"
    fi
    rm -f "$CLONE/$path"; nchg=$((nchg+1)); ndel=$((ndel+1))
  fi
done < "$CLONE/.nm/todo-$TAG"
# G4
( cd "$CLONE" && for s in $SYNC_PATHS; do
    if [ -d "$s" ]; then find "$s" \( -type f -o -type l \) ! -name '*.bctmp'; elif [ -e "$s" ]; then echo "$s"; fi
  done ) | csort > "$CLONE/.nm/disk-$TAG"
ccomm -23 "$CLONE/.nm/tree-$TAG" "$CLONE/.nm/disk-$TAG" | ccomm -23 - "$CLONE/.nm/ovpaths-$TAG" > "$CLONE/.nm/missing-$TAG"
ccomm -13 "$CLONE/.nm/tree-$TAG" "$CLONE/.nm/disk-$TAG" | ccomm -23 - "$CLONE/.nm/ovpaths-$TAG" > "$CLONE/.nm/extra-$TAG"
if [ -s "$CLONE/.nm/missing-$TAG" ] || [ -s "$CLONE/.nm/extra-$TAG" ]; then
  echo "[job] sync drift: $(wc -l < "$CLONE/.nm/missing-$TAG") missing, $(wc -l < "$CLONE/.nm/extra-$TAG") extra"
  head -5 "$CLONE/.nm/missing-$TAG" "$CLONE/.nm/extra-$TAG"
  sync_fail "PROBE FAILED: synced paths differ from origin/main@${SHA:0:9}"
fi
echo "[job] delta sync ${LAST:0:9}..${SHA:0:9}: $nchg files changed ($ndel deleted); $(wc -l < "$CLONE/.nm/tree-$TAG") synced paths match the tree"
rsync -rlc "$OV/" "$CLONE/" || sync_fail "PROBE FAILED: overlay apply"
cp "$CLONE/.nm/ovpaths-$TAG" "$CLONE/.nm/lastov"
echo "$SHA" > "$CLONE/.nm/base"
[ "$(md5sum < "$CLONE/lake-manifest.json" | cut -c1-32)" = "$(cat "$CLONE/.nm/manifest.md5")" ] \
  || summary_fail "PROBE FAILED: lake-manifest.json differs from the shared package tree; refusing to let lake write packages (infra)"
cd "$CLONE" || summary_fail "PROBE FAILED: no clone (infra)"
PY=/usr/bin/python3.11; [ -x "$PY" ] || PY=python3
"$PY" "$NMR/purge_stale_nm.py" "$CLONE" > "$LOG" 2>&1
export LAKE_ARTIFACT_CACHE=true LAKE_RESTORE_ARTIFACTS=true LAKE_CACHE_DIR="$NMR/lake-cache"
TS=""; [ -n "${CORES:-}" ] && TS="taskset -c $CORES"
echo "[job] $(hostname -s) cores=${CORES:-slurm} threads=$LEAN_NUM_THREADS base=$SHA lane=$LANE mods: $MODS" >> "$LOG"
T0=$(date +%s)
timeout 10800 nice -n 5 $TS lake build $MODS >> "$LOG" 2>&1; RC=$?
echo "EXIT=$RC" >> "$LOG"
echo "===== SUMMARY"
echo "lane $LANE tag $TAG host $(hostname -s) cores ${CORES:-slurm} base ${SHA:0:9} seconds $(( $(date +%s) - T0 )) log $LOG"
echo "--- errors (first 80 lines)"
grep -n -E '^error|error:|✖|declaration uses .sorry.|sorryAx' "$LOG" | head -80
echo "--- per-module"
for m in $MODS; do
  if grep -qF "Built $m " "$LOG" || grep -qE "Built ${m//./\\.}\$" "$LOG"; then echo "BUILT $m"
  elif grep -qF "Replayed $m" "$LOG"; then echo "REPLAYED $m"
  elif grep -qF " $m" "$LOG"; then echo "MENTIONED $m"
  else echo "UP-TO-DATE-OR-NOT-REACHED $m"; fi
done
echo "--- rebuilt modules: $(grep -c 'Built GroupApproximation\|Built Palomar' "$LOG")"
echo "--- compiled overlay files (olean newer than the source as built; a cache restore counts: same input hash)"
while IFS= read -r p; do
  case "$p" in *.lean) ;; *) continue;; esac
  b=".lake/build/lib/lean/${p%.lean}"
  if [ -f "$b.olean" ] && { [ "$b.olean" -nt "$p" ] || [ "$b.trace" -nt "$p" ] || [ "$b.olean.hash" -nt "$p" ]; }; then echo "COMPILED $p"; fi
done < "$CLONE/.nm/ovpaths-$TAG"
tail -3 "$LOG"
# Palomar libs build without warningAsError, so an incomplete proof there is only a warning. Gate on it, except for
# the deliberate holes of Palomar/*Challenge.lean.
HOLES=$(grep -E 'declaration uses .sorry.|sorryAx' "$LOG" | grep -vE 'Palomar/[A-Za-z0-9_]*Challenge\.lean:' | head -5)
# Axiom drivers: every `#print axioms` line of the overlay must come back as one closure from that overlay file
# (joined across line breaks), and no closure may name an axiom outside propext, Classical.choice and Quot.sound.
awk '
  acc != "" { acc = acc " " $0; if (index($0, "]")) { print acc; acc = "" }; next }
  /depends on axioms: \[/ { if (index($0, "]")) print; else acc = $0; next }
  /does not depend on any axioms/ { print }
' "$LOG" > "$CLONE/.nm/axjoined-$TAG"
: > "$CLONE/.nm/axmine-$TAG"
NPRINT=0
while IFS= read -r p; do
  case "$p" in *.lean) ;; *) continue;; esac
  n=$(grep -c '^#print axioms ' "$CLONE/$p" 2>/dev/null); NPRINT=$((NPRINT + ${n:-0}))
  grep -F "info: $p:" "$CLONE/.nm/axjoined-$TAG" >> "$CLONE/.nm/axmine-$TAG"
done < "$CLONE/.nm/ovpaths-$TAG"
sed -n -e "s/^.*: '\(.*\)' depends on axioms: \[\(.*\)\].*$/AXIOMS \1: [\2]/p" \
       -e "s/^.*: '\(.*\)' does not depend on any axioms.*$/AXIOMS \1: []/p" "$CLONE/.nm/axmine-$TAG" \
  | sed -e 's/  */ /g' -e 's/\[ /[/' > "$CLONE/.nm/axlines-$TAG"
NAX=$(wc -l < "$CLONE/.nm/axlines-$TAG" | tr -d ' ')
AXFAIL=""
if [ "$NPRINT" -gt 0 ] || [ "$NAX" -gt 0 ]; then
  echo "--- axiom closures printed by the overlay ($NAX printed, $NPRINT requested)"
  cat "$CLONE/.nm/axlines-$TAG"
  BADAX=$(sed -n 's/^AXIOMS .*: \[\(.*\)\]$/\1/p' "$CLONE/.nm/axlines-$TAG" | tr ',' '\n' | sed -e 's/^ *//' -e 's/ *$//' \
    | grep -v '^$' | grep -vxE 'propext|Classical\.choice|Quot\.sound' | LC_ALL=C sort -u | tr '\n' ' ')
  if [ -n "$BADAX" ]; then AXFAIL="axiom outside [propext, Classical.choice, Quot.sound]: $BADAX"
  elif [ "$NAX" != "$NPRINT" ]; then AXFAIL="printed $NAX axiom closures, but the overlay requests $NPRINT"; fi
fi
if [ $RC -eq 0 ] && grep -q 'Build completed successfully' "$LOG" && [ -z "$HOLES" ] && [ -z "$AXFAIL" ]; then
  echo "PROBE GREEN"
elif [ $RC -eq 0 ] && [ -n "$HOLES" ]; then
  echo "--- incomplete proofs outside a challenge file (first 5):"; printf '%s\n' "$HOLES"
  RC=6; echo "PROBE FAILED rc=$RC (incomplete proof outside a challenge file)"
elif [ $RC -eq 0 ] && [ -n "$AXFAIL" ]; then
  RC=7; echo "PROBE FAILED rc=$RC ($AXFAIL)"
else
  echo "PROBE FAILED rc=$RC"
fi
echo "REAL_EXIT=$RC"
rm -rf "$OV" "$CLONE/.nm/ovpaths-$TAG" "$CLONE/.nm/todo-$TAG" "$CLONE/.nm/tree-$TAG" "$CLONE/.nm/delta-$TAG" \
  "$CLONE/.nm/disk-$TAG" "$CLONE/.nm/missing-$TAG" "$CLONE/.nm/extra-$TAG" \
  "$CLONE/.nm/axjoined-$TAG" "$CLONE/.nm/axmine-$TAG" "$CLONE/.nm/axlines-$TAG"
exit $RC
